package com.tradingplatform.paper;
import com.tradingplatform.market.*; import com.tradingplatform.persistence.*; import java.math.*; import java.time.*; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import static com.tradingplatform.paper.PaperDtos.*;
@Service public class PaperTradingEngine { private final PaperAccountRepository accounts; private final PaperOrderRepository orders; private final PaperPositionRepository positions; private final InstrumentCatalogService catalog; private final PaperPriceService prices; private final ChargesCalculator charges; private final BigDecimal initial,maxDailyLoss,maxAllocation,slippage; private final int maxQty,maxOpen,maxTrades; private final boolean enabled;
 public PaperTradingEngine(PaperAccountRepository a,PaperOrderRepository o,PaperPositionRepository p,InstrumentCatalogService c,PaperPriceService price,ChargesCalculator charges,@Value("${trading.paper.enabled:true}") boolean enabled,@Value("${trading.paper.initial-balance:10000}") BigDecimal initial,@Value("${trading.paper.max-daily-loss:300}") BigDecimal daily,@Value("${trading.paper.max-allocation-per-trade:5000}") BigDecimal allocation,@Value("${trading.paper.max-position-quantity:1000}") int qty,@Value("${trading.paper.max-open-positions:10}") int open,@Value("${trading.paper.max-trades-per-day:50}") int trades,@Value("${trading.paper.slippage-percent:0}") BigDecimal slippage){accounts=a;orders=o;positions=p;catalog=c;prices=price;this.charges=charges;this.enabled=enabled;this.initial=initial;maxDailyLoss=daily;maxAllocation=allocation;maxQty=qty;maxOpen=open;maxTrades=trades;this.slippage=slippage;}
 @Transactional public Account account(){PaperAccountEntity a=getAccount(); return accountDto(a);} @Transactional public Account reset(){PaperAccountEntity a=getAccount();if(!positions.findByAccountIdAndStatus(a.id,PaperPositionStatus.OPEN).isEmpty())throw new IllegalStateException("Close all open positions before resetting the paper account");prices.clear();a.initialBalance=initial;a.availableCash=initial;a.usedMargin=BigDecimal.ZERO;a.realizedPnl=BigDecimal.ZERO;a.dailyRealizedPnl=BigDecimal.ZERO;a.updatedAt=Instant.now();accounts.save(a);return accountDto(a);} @Transactional public Order close(UUID positionId){PaperPositionEntity p=positions.findById(positionId).orElseThrow(()->new IllegalArgumentException("Unknown paper position"));if(p.status!=PaperPositionStatus.OPEN)throw new IllegalArgumentException("Position is already closed");return submit(new OrderRequest(p.symbol,p.side==PaperSide.BUY?PaperSide.SELL:PaperSide.BUY,p.quantity,null,null));}
 @Transactional public Order submit(OrderRequest request){PaperAccountEntity a=getAccount(); PaperOrderEntity o=new PaperOrderEntity();o.id=UUID.randomUUID();o.accountId=a.id;o.orderType="MARKET";o.status=PaperOrderStatus.CREATED;o.createdAt=Instant.now();o.charges=BigDecimal.ZERO;try{validate(request,a);Instrument i=catalog.resolveSymbol(request.symbol());o.instrumentKey=i.instrumentKey();o.symbol=i.symbol();PaperPriceService.Price price=prices.current(i);BigDecimal fill=slip(price.value(),request.side());o.side=request.side();o.quantity=request.quantity();o.requestedPrice=price.value();o.executionPrice=fill;o.status=PaperOrderStatus.VALIDATED;execute(a,o,i,request.stopLoss(),request.target());o.status=PaperOrderStatus.FILLED;o.filledAt=Instant.now();}catch(Exception e){o.status=PaperOrderStatus.REJECTED;o.rejectionReason=e.getMessage();o.side=request.side();o.quantity=request.quantity();if(o.symbol==null){o.symbol=request.symbol();}if(o.instrumentKey==null&&request.symbol()!=null){o.instrumentKey=request.symbol();}}orders.save(o);accounts.save(a);return orderDto(o);}
 private void validate(OrderRequest r,PaperAccountEntity a){if(!enabled)throw new IllegalStateException("Paper trading is disabled");if(r==null||r.symbol()==null||r.symbol().isBlank())throw new IllegalArgumentException("Symbol is required");if(r.quantity()<1||r.quantity()>maxQty)throw new IllegalArgumentException("Quantity must be between 1 and "+maxQty);if(a.dailyRealizedPnl.compareTo(maxDailyLoss.negate())<=0)throw new IllegalStateException("Paper trading halted: maximum daily loss reached");if(orders.countByAccountIdAndCreatedAtAfter(a.id,LocalDate.now(ZoneOffset.UTC).atStartOfDay().toInstant(ZoneOffset.UTC))>=maxTrades)throw new IllegalStateException("Maximum daily trades reached");}
 private void execute(PaperAccountEntity a,PaperOrderEntity o,Instrument i,BigDecimal sl,BigDecimal target){BigDecimal notional=o.executionPrice.multiply(BigDecimal.valueOf(o.quantity));if(notional.compareTo(maxAllocation)>0)throw new IllegalStateException("Maximum capital allocation per trade exceeded");PaperPositionEntity p=positions.findByAccountIdAndInstrumentKeyAndStatus(a.id,i.instrumentKey(),PaperPositionStatus.OPEN).orElse(null);if(p==null){if(positions.findByAccountIdAndStatus(a.id,PaperPositionStatus.OPEN).size()>=maxOpen)throw new IllegalStateException("Maximum open positions reached");open(a,o,i,sl,target,notional);return;}if(p.side==o.side){increase(a,o,p,notional);return;}reduce(a,o,p,notional);}
 private void open(PaperAccountEntity a,PaperOrderEntity o,Instrument i,BigDecimal sl,BigDecimal target,BigDecimal notional){if(a.availableCash.compareTo(notional)>0||a.availableCash.compareTo(notional)==0){a.availableCash=a.availableCash.subtract(notional); }else throw new IllegalStateException("Insufficient virtual balance");PaperPositionEntity p=new PaperPositionEntity();p.id=UUID.randomUUID();p.accountId=a.id;p.instrumentKey=i.instrumentKey();p.symbol=i.symbol();p.exchange=i.exchange();p.side=o.side;p.quantity=o.quantity;p.averageEntryPrice=o.executionPrice;p.currentPrice=o.executionPrice;p.unrealizedPnl=BigDecimal.ZERO;p.realizedPnl=BigDecimal.ZERO;p.stopLoss=sl;p.target=target;p.status=PaperPositionStatus.OPEN;p.openedAt=p.updatedAt=Instant.now();o.charges=charges.charge(notional);a.availableCash=a.availableCash.subtract(o.charges);positions.save(p);}
 private void increase(PaperAccountEntity a,PaperOrderEntity o,PaperPositionEntity p,BigDecimal notional){if(a.availableCash.compareTo(notional)>0||a.availableCash.compareTo(notional)==0){BigDecimal old=p.averageEntryPrice.multiply(BigDecimal.valueOf(p.quantity));p.quantity+=o.quantity;p.averageEntryPrice=old.add(notional).divide(BigDecimal.valueOf(p.quantity),6,RoundingMode.HALF_UP);a.availableCash=a.availableCash.subtract(notional);o.charges=charges.charge(notional);a.availableCash=a.availableCash.subtract(o.charges);p.updatedAt=Instant.now();positions.save(p);}else throw new IllegalStateException("Insufficient virtual balance");}
 private void reduce(PaperAccountEntity a,PaperOrderEntity o,PaperPositionEntity p,BigDecimal notional){if(o.quantity>p.quantity)throw new IllegalArgumentException("Order quantity exceeds open position; close then open a new position");BigDecimal gross=o.executionPrice.subtract(p.averageEntryPrice).multiply(BigDecimal.valueOf(o.quantity)).multiply(p.side==PaperSide.BUY?BigDecimal.ONE:BigDecimal.ONE.negate());o.charges=charges.charge(notional);BigDecimal net=gross.subtract(o.charges).setScale(2,RoundingMode.HALF_UP);p.realizedPnl=p.realizedPnl.add(net).setScale(2,RoundingMode.HALF_UP);a.realizedPnl=a.realizedPnl.add(net).setScale(2,RoundingMode.HALF_UP);a.dailyRealizedPnl=a.dailyRealizedPnl.add(net).setScale(2,RoundingMode.HALF_UP);a.availableCash=a.availableCash.add(notional).subtract(o.charges);p.quantity-=o.quantity;p.currentPrice=o.executionPrice;p.unrealizedPnl=unrealized(p);p.updatedAt=Instant.now();if(p.quantity==0)p.status=PaperPositionStatus.CLOSED;positions.save(p);}
 @Transactional public void onPrice(String key,BigDecimal price){for(PaperPositionEntity p:positions.findByInstrumentKeyAndStatus(key,PaperPositionStatus.OPEN)){p.currentPrice=price;p.unrealizedPnl=unrealized(p);p.updatedAt=Instant.now();positions.save(p);if((p.side==PaperSide.BUY&&((p.stopLoss!=null&&price.compareTo(p.stopLoss)<=0)||(p.target!=null&&price.compareTo(p.target)>=0)))||(p.side==PaperSide.SELL&&((p.stopLoss!=null&&price.compareTo(p.stopLoss)>=0)||(p.target!=null&&price.compareTo(p.target)<=0)))){PaperOrderEntity o=new PaperOrderEntity();o.id=UUID.randomUUID();o.accountId=p.accountId;o.instrumentKey=p.instrumentKey;o.symbol=p.symbol;o.side=p.side==PaperSide.BUY?PaperSide.SELL:PaperSide.BUY;o.quantity=p.quantity;o.requestedPrice=price;o.executionPrice=price;o.orderType="MARKET";o.status=PaperOrderStatus.FILLED;o.createdAt=o.filledAt=Instant.now();PaperAccountEntity a=accounts.findById(p.accountId).orElseThrow();reduce(a,o,p,price.multiply(BigDecimal.valueOf(o.quantity)));orders.save(o);accounts.save(a);}}}
 public List<Position> positions(){PaperAccountEntity a=getAccount();return positions.findByAccountIdAndStatus(a.id,PaperPositionStatus.OPEN).stream().map(this::positionDto).toList();} public List<Order> orders(){PaperAccountEntity a=getAccount();return orders.findTop200ByAccountIdOrderByCreatedAtDesc(a.id).stream().map(this::orderDto).toList();}
 private PaperAccountEntity getAccount(){return accounts.findFirstByOrderByCreatedAtAsc().orElseGet(()->{PaperAccountEntity a=new PaperAccountEntity();a.id=UUID.randomUUID();a.initialBalance=initial;a.availableCash=initial;a.usedMargin=BigDecimal.ZERO;a.realizedPnl=BigDecimal.ZERO;a.dailyRealizedPnl=BigDecimal.ZERO;a.createdAt=a.updatedAt=Instant.now();return accounts.save(a);});} private BigDecimal slip(BigDecimal p,PaperSide s){return p.multiply(BigDecimal.ONE.add(slippage.divide(BigDecimal.valueOf(100),8,RoundingMode.HALF_UP).multiply(s==PaperSide.BUY?BigDecimal.ONE:BigDecimal.ONE.negate())));} private BigDecimal unrealized(PaperPositionEntity p){return p.currentPrice.subtract(p.averageEntryPrice).multiply(BigDecimal.valueOf(p.quantity)).multiply(p.side==PaperSide.BUY?BigDecimal.ONE:BigDecimal.ONE.negate()).setScale(2,RoundingMode.HALF_UP);} private Account accountDto(PaperAccountEntity a){BigDecimal u=positions.findByAccountIdAndStatus(a.id,PaperPositionStatus.OPEN).stream().map(x->x.unrealizedPnl).reduce(BigDecimal.ZERO,BigDecimal::add).setScale(2,RoundingMode.HALF_UP);BigDecimal realized=a.realizedPnl.setScale(2,RoundingMode.HALF_UP);BigDecimal daily=a.dailyRealizedPnl.setScale(2,RoundingMode.HALF_UP);return new Account(a.id,a.initialBalance,a.availableCash,a.usedMargin,realized,u,realized.add(u),daily);} private Position positionDto(PaperPositionEntity p){return new Position(p.id,p.symbol,p.exchange,p.side,p.quantity,p.averageEntryPrice,p.currentPrice,p.unrealizedPnl,p.realizedPnl,p.stopLoss,p.target,p.status,p.openedAt);} private Order orderDto(PaperOrderEntity o){return new Order(o.id,o.symbol,o.side,o.quantity,o.requestedPrice,o.executionPrice,o.status,o.charges,o.rejectionReason,o.createdAt);} }
